import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.GraphScopeOptimizer;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.ParentReferenceChecker;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

class GraphPatternFilterOptimizerTest {

	@Test
	void equalityRestrictsOnlyTheSelectorOccurrence() {
		TupleExpr plan = parse("SELECT * { GRAPH ?g { FILTER(!BOUND(?g)) } FILTER(?g = <urn:g1>) }");
		optimize(plan, GraphJoinOptimization.FORCE_INDEPENDENT);
		assertThat(graphs(plan)).singleElement().satisfies(graph -> {
			assertThat(graph.getGraphName().getValue()).isEqualTo(SimpleValueFactory.getInstance().createIRI("urn:g1"));
			assertThat(graph.getGraphName().isConstant()).isFalse();
			assertThat(graph.getArg()).isInstanceOf(Filter.class);
			assertThat(graph.getArg().toString()).doesNotContain("value=urn:g1");
		});
	}

	@Test
	void scalarFilterMovesInsideVariableGraph() {
		TupleExpr plan = parse("SELECT * { GRAPH ?g { ?s <urn:p> ?o } FILTER(?o > 1) }");
		optimize(plan, GraphJoinOptimization.FORCE_INDEPENDENT);
		assertThat(graphs(plan)).singleElement().satisfies(graph -> {
			assertThat(graph.getArg()).isInstanceOf(Filter.class);
			assertThat(graph.getParentNode()).isNotInstanceOf(Filter.class);
		});
	}

	@Test
	void scalarFilterAllowsConstantGraphLowering() {
		TupleExpr plan = parse("SELECT * { GRAPH <urn:g1> { ?s <urn:p> ?o FILTER(?o > 1) } }");
		optimize(plan, GraphJoinOptimization.OFF);
		assertThat(graphs(plan)).isEmpty();
		List<StatementPattern> statements = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern statement) {
				statements.add(statement);
			}
		});
		assertThat(statements).singleElement().satisfies(statement -> {
			assertThat(statement.getScope()).isEqualTo(StatementPattern.Scope.NAMED_CONTEXTS);
			assertThat(statement.getContextVar().getValue())
					.isEqualTo(SimpleValueFactory.getInstance().createIRI("urn:g1"));
		});
	}

	private static TupleExpr parse(String sparql) {
		return new QueryRoot(QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, sparql, null,
				QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH)).getTupleExpr());
	}

	private static void optimize(TupleExpr plan, GraphJoinOptimization mode) {
		GraphScopeOptimizer optimizer = new GraphScopeOptimizer(
				QueryExecutionPolicy.DEFAULT.withGraphJoinOptimization(mode));
		optimizer.optimize(plan, null, EmptyBindingSet.getInstance());
		new ParentReferenceChecker(optimizer).optimize(plan, null, EmptyBindingSet.getInstance());
	}

	private static List<Graph> graphs(TupleExpr plan) {
		List<Graph> graphs = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Graph graph) {
				graphs.add(graph);
				super.meet(graph);
			}
		});
		return graphs;
	}
}
